package com.jonnyutah12.thaumcraftclassic.research;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.List;

/**
 * Loads the extracted research graph from
 * {@code data/thaumcraft/research/{categories,entries}.json}.
 *
 * <p>The JSON is generated by scripts/extract_research_graph.py from the
 * decompiled original (docs/research-graph-notes.md). The loader enforces
 * the file-level contract: format version 1, and the declared entry count
 * matching the embedded array.</p>
 */
public final class ResearchGraphLoader {

    public static final int FORMAT_VERSION = 1;
    public static final String CATEGORIES_RESOURCE = "data/thaumcraft/research/categories.json";
    public static final String ENTRIES_RESOURCE = "data/thaumcraft/research/entries.json";

    private record CategoryFile(int formatVersion, String source, List<ResearchCategoryData> categories) {
    }

    private record EntryFile(int formatVersion, String source, int entryCount, List<ResearchEntryData> entries) {
    }

    /** Loads the graph shipped in this mod's resources. */
    public static ResearchGraph loadDefault() {
        ClassLoader loader = ResearchGraphLoader.class.getClassLoader();
        try (InputStream categories = loader.getResourceAsStream(CATEGORIES_RESOURCE);
             InputStream entries = loader.getResourceAsStream(ENTRIES_RESOURCE)) {
            if (categories == null || entries == null) {
                throw new IllegalStateException("research graph resources missing from the classpath");
            }
            return load(categories, entries);
        } catch (IOException e) {
            throw new IllegalStateException("failed to read research graph resources", e);
        }
    }

    public static ResearchGraph load(InputStream categoriesJson, InputStream entriesJson) {
        return load(new InputStreamReader(categoriesJson, StandardCharsets.UTF_8),
                new InputStreamReader(entriesJson, StandardCharsets.UTF_8));
    }

    public static ResearchGraph load(Reader categoriesJson, Reader entriesJson) {
        Gson gson = new Gson();
        try {
            CategoryFile categories = gson.fromJson(categoriesJson, CategoryFile.class);
            EntryFile entries = gson.fromJson(entriesJson, EntryFile.class);
            if (categories == null || entries == null) {
                throw new IllegalArgumentException("empty research graph file");
            }
            if (categories.formatVersion() != FORMAT_VERSION || entries.formatVersion() != FORMAT_VERSION) {
                throw new IllegalArgumentException("unsupported research graph format version");
            }
            if (categories.categories() == null || entries.entries() == null) {
                throw new IllegalArgumentException("research graph files carry no arrays");
            }
            if (entries.entryCount() != entries.entries().size()) {
                throw new IllegalArgumentException("entryCount " + entries.entryCount()
                        + " does not match embedded entries " + entries.entries().size());
            }
            return new ResearchGraph(categories.categories(), entries.entries());
        } catch (JsonSyntaxException e) {
            throw new IllegalArgumentException("research graph JSON is malformed", e);
        }
    }

    private ResearchGraphLoader() {
    }
}
